function Page_CommonActLuckRotaryTableView:initialize()

end

function Page_CommonActLuckRotaryTableView:OnAwake()
    self.cs_RotaryTableAnim = UIUtil.GetTypeChildWightByParent("rewardTransParent",self.gameObject,typeof(CS.RotaryTableAnim))

    self.rewardTransParent=UIUtil.GetChild("rewardTransParent",self.gameObject)
    self.haloEffectTrans = UIUtil.GetChild("haloEffectTrans",self.gameObject)

end

function Page_CommonActLuckRotaryTableView:GetPurchaseByIndex(index)
    local table = stringSplit(self.actConfig.itemids,':')
    if #table<index then
        return -1
    else
        return tonumber(table[index])
    end
end

function Page_CommonActLuckRotaryTableView:OnOpen()
    local _config = CommonHelper:GetTableDataByID(ConfigNames.dictcalc_config, CommonCfgKey.SpringFestivalID)

    local actId=  CommonFestivalDataManager:Get():GetActivityDataIDByType(CommonFestivalType.ActLuckRotaryTable)
	print("actId",CommonFestivalType.ActLuckRotaryTable,actId)
    ---@type act_bussiness_config_cell
    local cfg=CommonHelper:GetTableDataByID(ConfigNames.act_bussiness_config,actId)
    LuckRotaryTableConfigDefault.SpringFestival = LuckRotaryTableConfig(actId,  tonumber(cfg.itemids))
    LuckRotaryTableDataManager:Get():SetCurConfig(LuckRotaryTableConfigDefault.SpringFestival)

    local _goodsType, _goodsData = CommonHelper:GetPropTypeById(tonumber(cfg.itemids))
    local _goodsIconImg = _goodsType == PropType.Part and _goodsData.icon or _goodsData.icon .. ".png"
    CommonHelper:GetComponentSetUITexture("ticketIcon_2",  self.gameObject, _goodsIconImg, UIModuleID.CommonFestival)

    CommonHelper:SetText("time/###time", self.gameObject,self:GetDataTimeString())
    self.cs_RotaryTableAnim:Init(self.haloEffectTrans.transform)
    CommonHelper:HButtonSetCallback("BtnHelp",self.gameObject,function(btn)
        CommonHelper:ShowHelpView(PageDetailType.ActLuckRotaryTable,nil,nil,true    )
    end)
    self.BtnProb=CommonHelper:HButtonSetCallback("BtnProb",self.gameObject,function (hbtn)
        CommonHelper:ShowHelpView(PageDetailType.ActLuckRotaryTableProb,nil,HelpStyleType.YellowStyle,true)
    end)
    CommonHelper:SetHButtonClick(self.BtnProb,HVersionManager:GetServerFunctionIsFlag(CdnFunctionKey.BtnProb),true)
    ---@type act_gift_config_cell
    local actGiftData = CommonHelper:GetTableDataByID(ConfigNames.act_gift_config, self:GetPurchaseByIndex(1))
    if actGiftData then
        self.giftbagBtn = CommonHelper:HButtonSetCallback("giftbagBtn",self.gameObject,function (hbtn)
            CommonHelper:ShowPartInfoByCfgId(tonumber(actGiftData.awardids), UIModuleID.CommonActLuckRotaryTable, false)
        end)
        self.directPurchase = CommonHelper:HButtonSetCallback("directPurchase",self.gameObject,function (hbtn)
            CommonHelper:ChargeMoneyByID(self:GetPurchaseByIndex(1))

        end)
        CommonHelper:SetBtnIsRmbOrToken(self.directPurchase,CommonHelper:GetChargeCfgByAreaAndItemId(self:GetPurchaseByIndex(1)))
    end

    ---@type dictcharge_config_cell
    local chargeData = CommonHelper:GetChargeCfgByAreaAndItemId(self:GetPurchaseByIndex(1))
    if chargeData then
        CommonHelper:SetText("###priceText",self.gameObject,chargeData.pricename)
        CommonHelper:SetText("###directPurchaseName",self.gameObject,CommonHelper:GetTempStr_Default(actGiftData.name))
        CommonHelper:SetText("###directNum",self.gameObject, string.format(CommonHelper:GetTempStr_Default(TemplateStringID.LuckRotaryLotteryTicketNum),actGiftData.awardnums) )
    end

    ---@type dictarticle_config_cell
    local configData = CommonHelper:GetTableDataByID(ConfigNames.article_config, tonumber(LuckRotaryTableDataManager:Get():GetCurConfig().propId))
    CommonHelper:GetComponentSetUITexture("ticketIcon",self.gameObject,configData.icon..".png",self:GetUIModuleID())
    CommonHelper:GetComponentSetUITexture("directPurchaseIcon",self.gameObject, configData.icon..".png",self:GetUIModuleID())

    local luckRotaryTables = LuckRotaryTableDataManager:Get():GetLuckRotaryTable()
    for i, v in pairs(luckRotaryTables) do
        self:SetItem(i-1,v)
    end

    self.aniSwitch=false
    self.aniSwitchBtn = CommonHelper:HButtonSetCallback("aniSwitch",self.gameObject,function(btn)
        self:AniSwitch()
    end)
    self:AniSwitch()

    CommonHelper:HButtonSetCallback("drawBtnOne",self.gameObject,function (hbtn)
        if LuckRotaryTableDataManager:Get():GetLotteryTicketNum()>0 then
            CommonFestivalSubSystem:Get():SendMsg_LuckTable(1,self.actConfig.C_ID)
            CommonHelper:PlayGuideScreenEffectUIMask()
        else
            CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.LuckRotaryLotteryTicketNotEnough))
        end
    end)
    self.drawBtnMult = CommonHelper:HButtonSetCallback("drawBtnMult",self.gameObject,function (hbtn)
        local num=  LuckRotaryTableDataManager:Get():GetLotteryTicketNum()
        if num>0then
            num = num>10 and 10 or num
            CommonFestivalSubSystem:Get():SendMsg_LuckTable(num,self.actConfig.C_ID)
            CommonHelper:PlayGuideScreenEffectUIMask()
        else
            CommonTipsHelper:ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.LuckRotaryLotteryTicketNotEnough))
        end
    end)
    self:RefreshLotteryTicket()
end

---@param index number
---@param luckRotaryTableData LuckRotaryTableData
function Page_CommonActLuckRotaryTableView:SetItem(index,luckRotaryTableData)
    local itemCount = self.rewardTransParent.transform.childCount
    local propType ,configData = CommonHelper:GetPropTypeById(tonumber(luckRotaryTableData:GetPropsId()))
    if index < itemCount and configData then
        local itemObj=  self.rewardTransParent.transform:GetChild(index).gameObject
        local icon ="uitex_sucai_default.png"
        local name =""
        if propType==PropType.TracKSegment then
            icon=configData.icon
            name = configData.name
        elseif propType==PropType.Part then
            icon=configData.icon
            name=configData.partname
        elseif propType==PropType.Article then
            icon=configData.icon..".png"
            name=configData.name
        end
        CommonHelper:GetComponentSetUITexture("icon",itemObj,icon,self:GetUIModuleID())
        CommonHelper:SetText("###iconNum",itemObj,string.format(CommonHelper:GetTempStr_Default(TemplateStringID.LuckRotaryAwardPublicity),ClientDataManager:Get():GetTemplateString(name) ,luckRotaryTableData:GetPropsNum()))
        CommonHelper:SetGameObjectActive("commonImg",itemObj,not luckRotaryTableData:IsHitFlag())
        CommonHelper:SetGameObjectActive("specialImg",itemObj, luckRotaryTableData:IsHitFlag())
        CommonHelper:HButtonSetCallback("DetailsBtn",itemObj,function (hbtn)
            CommonHelper:ShowPartInfoByCfgId(luckRotaryTableData:GetPropsId(), UIModuleID.CommonAct)
        end)
    end
end

function Page_CommonActLuckRotaryTableView:RefreshLotteryTicket()
    local num = LuckRotaryTableDataManager:Get():GetLotteryTicketNum()
    CommonHelper:SetText("###lotteryTicketNum2",self.gameObject,
            string.format(CommonHelper:GetTempStr_Default(TemplateStringID.LuckRotaryLotteryDrawSurplusNum), num))
    if  num == 0 then
        num = 1
    elseif num>10 then
        num = 10
    end
    CommonHelper:SetText("###num",self.drawBtnMult.gameObject,
            string.format(CommonHelper:GetTempStr_Default(TemplateStringID.LuckRotaryLotteryDrawMultNum), num))
end

function Page_CommonActLuckRotaryTableView:AniSwitch()
    self.aniSwitch=not self.aniSwitch
    --CommonHelper:SetGameObjectActive("checked",self.aniSwitchBtn.gameObject,self.aniSwitch)
    CommonHelper:SetGameObjectActive("unChecked",self.aniSwitchBtn.gameObject,not self.aniSwitch)
end

function Page_CommonActLuckRotaryTableView:RetLuckyTable(data)
    self:RefreshLotteryTicket()
    CommonHelper:CSGameObjectSetActive(self.haloEffectTrans,true)
    local aniCallBack=data[1]
    table.remove(data,1)
    if self.aniSwitch then
        if data and type(data[1])=="table" and #data[1]>1  then
            self:StartDrawAniMult(data[1],aniCallBack)
        elseif data and type(data[1])=="table"and #data[1]>0   then
            CommonHelper:SetGameObjectActive("haloEffectImage",self.haloEffectTrans,true)
            CommonHelper:SetGameObjectActive("checkedImage",self.haloEffectTrans,false)
            self.cs_RotaryTableAnim:StartLuckyDrawOne(data[1][1]-1,function(index)
                --CommonHelper:CSGameObjectSetActive(self.haloEffectTrans,false)
                CommonHelper:SetGameObjectActive("haloEffectImage",self.haloEffectTrans,false)
                CommonHelper:SetGameObjectActive("checkedImage",self.haloEffectTrans,true)
                if aniCallBack then
                    aniCallBack()
                end
                CommonHelper:CloseGuideScreenEffectUIMask()
            end)
        else
            logError("奖励没有吗？？？？？？？？")
        end
    else
        self.cs_RotaryTableAnim:SetHaloResult(data[1][#data[1]]-1)
        CommonHelper:SetGameObjectActive("haloEffectImage",self.haloEffectTrans,false)
        CommonHelper:SetGameObjectActive("checkedImage",self.haloEffectTrans,true)
        if aniCallBack and type(aniCallBack)=="function" then
            aniCallBack()
        end
        CommonHelper:CloseGuideScreenEffectUIMask()
    end
end

function Page_CommonActLuckRotaryTableView:StartDrawAniMult(data,aniCallBack)
    if #data>0 then
        CommonHelper:SetGameObjectActive("haloEffectImage",self.haloEffectTrans,true)
        CommonHelper:SetGameObjectActive("checkedImage",self.haloEffectTrans,false)
        self.cs_RotaryTableAnim:StartLuckyDrawMult(data[1]-1,function(index)
            CommonHelper:SetGameObjectActive("haloEffectImage",self.haloEffectTrans,false)
            CommonHelper:SetGameObjectActive("checkedImage",self.haloEffectTrans,true)
            if (index==-1 or  #data==1 )and aniCallBack then
                aniCallBack()
                CommonHelper:CloseGuideScreenEffectUIMask()
            else
                table.remove(data,1)
                self.coroutine= cs_coroutine.start(function()
                    coroutine.yield(CS.UnityEngine.WaitForSeconds(0.6))
                    self:StartDrawAniMult(data,aniCallBack)
                end)
            end
        end)
    end
end

function Page_CommonActLuckRotaryTableView:OnClose()
    if self.coroutine then
        cs_coroutine.stop(self.coroutine)
    end
    self.cs_RotaryTableAnim:SetHaloResult(0)
end